/* Browser-only MVP. No model requests, external libraries or remote data calls. */
(function () {
  'use strict';
  const C=window.AtlasCore,KEY='atlas-onboard-mvp-v2';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num=(v,d=0)=>Number.isFinite(v)?v.toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d}):'—';
  const pct=v=>Number.isFinite(v)?num(v,1)+'%':'Not available';
  const date=v=>v&&Number.isFinite(Date.parse(v))?new Date(v).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):'Not recorded';
  const time=v=>new Date(v).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});
  let st,storageWarning=false;
  try{st=JSON.parse(localStorage.getItem(KEY));}catch{}
  if(!st||st.version!==C.VERSION||!Array.isArray(st.plants)||!st.plants.length)st=C.initial();
  st.templates=st.templates||[];
  const ui={filter:'all',mappingFilter:'all',caseFilter:'all',activityScope:'all'};
  let toastTimer;
  const paths={
    grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',
    factory:'M3 21V10l6 3V7l6 3V3h5v18H3ZM6 17h1m4 0h1m4 0h1',
    upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',
    map:'M3 6h6v4H3zM15 14h6v4h-6zM9 8h5a4 4 0 0 1 4 4v2M15 5h6M3 18h6',
    check:'m5 12 4 4L19 6',shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7l-9-4Zm-4 9 3 3 5-5',
    chart:'M3 3v18h18M7 16v-5m5 5V7m5 9V4',flag:'M5 21V4m0 0c5-4 8 4 14 0v10c-6 4-9-4-14 0',
    activity:'M3 12h4l3-8 4 16 3-8h4',arrow:'M4 12h16m-5-5 5 5-5 5',plus:'M12 5v14M5 12h14',
    file:'M5 3h9l5 5v13H5V3Zm9 0v6h5M8 13h8m-8 4h6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v6l4 2',
    down:'M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4',search:'M11 3a8 8 0 1 0 0 16 8 8 0 0 0 0-16Zm6 14 5 5',
    close:'m6 6 12 12M6 18 18 6',chevron:'m9 5 7 7-7 7',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm-3 6a3 3 0 1 1 4 3c-1 .5-1 1-1 2m0 3h.01',
    layers:'m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5',edit:'m15 4 5 5-11 11-6 1 1-6L15 4Zm-3 3 5 5',
    link:'m9 8 3-3a5 5 0 0 1 7 7l-3 3M8 9l-3 3a5 5 0 0 0 7 7l3-3m-7-1 8-8',refresh:'M20 10a8 8 0 1 0-1 7M20 3v7h-7',
    user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM4 21v-3a8 8 0 0 1 16 0v3',alert:'m12 3 10 18H2L12 3Zm0 6v5m0 3h.01'
  };
  const icon=(id,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[id]||paths.grid}"/></svg>`;
  const button=(label,action,opts={})=>`<button type="button" class="btn ${opts.cls||''}" data-action="${action}" ${opts.data?`data-value="${esc(opts.data)}"`:''} ${opts.disabled?'disabled':''}>${opts.icon?icon(opts.icon):''}${label}</button>`;
  const navButton=(label,view,cls='btn secondary',ico='arrow')=>`<button type="button" class="${cls}" data-nav="${view}">${label} ${icon(ico)}</button>`;
  const pill=(text,tone='')=>`<span class="pill ${tone}">${text}</span>`;
  const p=()=>st.plants.find(x=>x.id===st.selected)||st.plants[0];
  function save(){try{localStorage.setItem(KEY,JSON.stringify(st));storageWarning=false;}catch{storageWarning=true;}}
  function toast(message){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),4500);}
  function record(action,detail,plant=p()) {st.activity.unshift({id:C.uid(),at:new Date().toISOString(),plant:plant.id,actor:st.role,action,detail});st.activity=st.activity.slice(0,500);save();}
  function go(view){st.view=view;save();render();window.scrollTo({top:0,behavior:'instant'});}
  function changePlant(id,view){st.selected=id;if(view)st.view=view;save();render();window.scrollTo({top:0,behavior:'instant'});}
  function status(plant){if(plant.report)return ['Reporting',''];if(plant.validation?.pass)return ['Awaiting approval','warn'];if(plant.source)return ['Needs review','warn'];return ['Awaiting source','neutral'];}
  function progress(plant){return [Object.values(plant.readiness).every(Boolean),!!plant.source,plant.mappings.length>0&&plant.mappings.every(m=>m.reviewed&&m.target!=='unresolved'),!!plant.validation?.pass,!!plant.report].filter(Boolean).length;}
  function next(plant){if(!Object.values(plant.readiness).every(Boolean))return ['Confirm plant readiness','setup'];if(!plant.source)return ['Add source data','data'];if(!plant.validation?.pass)return ['Review field mappings','mapping'];if(!plant.report)return ['Complete approvals','approvals'];return ['View operating report','performance'];}
  function title(k,t,d,actions=''){return `<div class="intro"><div><div class="eyebrow">${k}</div><h1>${t}</h1><div class="sub">${d}</div></div><div class="intro-actions">${actions}</div></div>`;}
  function plantSelect(){return `<label class="plant-switch">${icon('factory')}<select id="plant-select" aria-label="Selected plant">${st.plants.map(x=>`<option value="${esc(x.id)}" ${x.id===p().id?'selected':''}>${esc(x.name)} · ${esc(x.id)}</option>`).join('')}</select></label>`;}
  function scope(){const x=p();return `<div class="scope-banner">${icon('factory')}<strong>${esc(x.name)}</strong><span>·</span><span>${esc(x.line||'Line not set')}</span><span>·</span><span>${esc(x.product||'Product not set')}</span><span class="right">Reporting contract v1 · ${pill('Local workspace','neutral')}</span></div>`;}
  function steps(){const x=p(),checks=[Object.values(x.readiness).every(Boolean),!!x.source,x.mappings.length>0&&x.mappings.every(m=>m.reviewed&&m.target!=='unresolved'),!!x.validation?.pass,!!x.report];const first=checks.indexOf(false);return `<div class="steps">${[['Plant setup','setup'],['Source data','data'],['Map & review','mapping'],['Validate','validation'],['Approve & publish','approvals']].map(([label,view],i)=>`<button class="step ${checks[i]?'done':i===first?'current':''}" data-nav="${view}"><i>${checks[i]?'✓':i+1}</i>${label}</button>`).join('')}</div>`;}
  function kpis(items){return `<div class="kpis">${items.map(([label,value,note,ico])=>`<div class="kpi"><div class="kpi-top"><span>${label}</span>${icon(ico||'chart')}</div><strong>${value}</strong><small>${note}</small></div>`).join('')}</div>`;}
  function empty(titleText,description,action=''){return `<div class="empty">${icon('layers')}<h3>${titleText}</h3><p>${description}</p>${action}</div>`;}
  const nav=[['overview','grid','Overview'],['setup','factory','Plant setup'],['data','upload','Source data'],['mapping','map','Mapping review'],['validation','shield','Validation'],['approvals','check','Approvals'],['performance','chart','Operating reports'],['investigations','flag','Investigations'],['activity','activity','Activity & evidence']];
  function render(){
    const openCases=st.investigations.filter(c=>c.status!=='Resolved').length;
    const view=nav.find(n=>n[0]===st.view)?st.view:'overview';
    const pages={overview,setup,data:sourceData,mapping,validation,approvals,performance,investigations,activity};
    document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">A</span><strong>atlas<span>onboard</span></strong></div><div class="workspace-label">Integration workspace</div><nav class="nav" aria-label="Workspace navigation">${nav.map(([id,ico,label],i)=>`${i===6?'<div class="navgroup">':''}<button data-nav="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ico)}${label}${id==='investigations'&&openCases?`<em>${openCases}</em>`:''}</button>${i===nav.length-1?'</div>':''}`).join('')}</nav><div class="side-note"><strong>${icon('layers')}Your first trusted report</strong>One clear path from local plant records to an accountable decision.<button data-action="guide">Explore the demo ${icon('arrow')}</button></div><div class="side-person"><span class="avatar">MC</span><div>Case study workspace<small>Synthetic demonstration</small></div><button class="iconbtn right" data-action="help" aria-label="About this MVP">${icon('help')}</button></div></aside><div class="main"><header class="topbar"><div class="breadcrumb">Workspace ${icon('chevron')}<b>${esc(nav.find(n=>n[0]===view)?.[2])}</b></div><div class="top-actions"><button class="ai-status" data-action="ai-info"><i></i> Prototype mode</button><label for="role-select">Demo role</label><select id="role-select" aria-label="Demo role">${['Integration lead','Data steward','Plant operations','Leadership'].map(r=>`<option ${r===st.role?'selected':''}>${r}</option>`).join('')}</select><div class="top-avatar">${st.role.split(' ').map(s=>s[0]).join('')}</div></div></header><main class="content">${storageWarning?'<div class="hint warn space">Browser storage is unavailable or full. This session still works; download a workspace export to retain changes.</div>':''}${pages[view]()}<footer class="footer"><span>ATLAS ONBOARD <span style="opacity:.4">/</span> MVP 02</span><span>Synthetic sample data · Browser-local state · Demo roles</span><button class="textbtn tiny" data-action="help">About this workspace ${icon('help')}</button></footer></main></div></div>`;
    const zone=document.getElementById('dropzone');if(zone){['dragenter','dragover'].forEach(type=>zone.addEventListener(type,e=>{e.preventDefault();zone.classList.add('drag');}));['dragleave','drop'].forEach(type=>zone.addEventListener(type,e=>{e.preventDefault();zone.classList.remove('drag');}));zone.addEventListener('drop',e=>{if(e.dataTransfer.files[0])receiveFile(e.dataTransfer.files[0]);});}
  }
  function plantRows(){const list=st.plants.filter(x=>ui.filter==='all'||(ui.filter==='reporting'?!!x.report:!x.report));return list.map(x=>{const s=status(x),n=next(x);return `<tr data-plant-row data-search="${esc((x.name+' '+x.id).toLowerCase())}"><td><div class="plant-name"><span class="plant-symbol">${icon('factory')}</span><div><strong>${esc(x.name)}</strong><small>${esc(x.id)} · ${esc(x.line||'Scope pending')}</small></div></div></td><td>${pill(s[0],s[1])}</td><td><span class="progress-label">${progress(x)} / 5 milestones</span><div class="progress"><span style="width:${progress(x)*20}%"></span></div></td><td><span class="tiny muted">${esc(x.owners.integration||'Unassigned')}</span></td><td><button class="textbtn" data-action="open-plant" data-value="${esc(x.id)}">${x.report?'View report':'Continue'} ${icon('arrow')}</button></td></tr>`;}).join('');}
  function miniActivity(items){return items.map(a=>`<div class="activity-item"><span class="activity-icon">${icon(a.action.includes('report')?'chart':a.action.includes('review')?'check':'activity')}</span><div><strong>${esc(a.action)}</strong><small>${esc(st.plants.find(x=>x.id===a.plant)?.name||a.plant)} · ${esc(a.actor)}</small></div><time>${time(a.at)}</time></div>`).join('')||'<p class="small muted">Your workflow activity will appear here.</p>';}
  function factoryVisual(){return `<div class="hero-visual" aria-hidden="true"><svg viewBox="0 0 280 180"><defs><linearGradient id="roof" x2="1" y2="1"><stop stop-color="#58704b"/><stop offset="1" stop-color="#304c36"/></linearGradient></defs><ellipse cx="146" cy="150" rx="104" ry="19" fill="#86966a" opacity=".17"/><path d="M50 98 132 53 229 105 148 151Z" fill="#c0cda9"/><path d="m50 98 98 53v-47L50 54Z" fill="#f0f4e7"/><path d="m148 104 81-45v46l-81 46Z" fill="#9caf8a"/><path d="m50 54 31-18 34 17 29-17 34 17 18-9 33 15-81 45Z" fill="url(#roof)"/><path d="m65 87 14 7v23l-14-7Zm26 14 14 7v23l-14-7Zm26 14 14 7v23l-14-7Z" fill="#90a07c"/><path d="m169 101 40-22v28l-40 22Z" fill="#526e4d"/><path d="m178 54 10 5V22l-10-5Z" fill="#b2bf9c"/><path d="m188 59 10-5V17l-10 5Z" fill="#80956a"/><path d="m178 17 10-5 10 5-10 5Z" fill="#c7d3b2"/><g stroke="#e9efdd" stroke-width="1"><path d="m174 112 29-16m-29 23 29-16"/></g><circle cx="65" cy="30" r="11" fill="#eff5e5"/><path d="m61 30 3 3 6-7" stroke="#78955d" stroke-width="2" fill="none"/><path d="m73 35 17 10" stroke="#b9c8a2" stroke-dasharray="3 3" fill="none"/><circle cx="241" cy="129" r="12" fill="#eef3e2"/><path d="M236 132v-7m5 7v-11m5 11v-5" stroke="#7d9862" stroke-width="2" fill="none"/><path d="m230 129-20-10" stroke="#b9c8a2" stroke-dasharray="3 3" fill="none"/></svg><span class="hero-caption">CONNECT · UNDERSTAND · TRUST</span></div>`;}
  function overview(){
    const reporting=st.plants.filter(x=>x.report).length,pending=st.plants.filter(x=>!x.report).length,issues=st.plants.reduce((n,x)=>n+C.deviations(x).length,0),n=next(p());
    return title('Plant integration, made repeatable','Every plant. A clearer picture.','Bring new sites into trusted reporting, one accountable step at a time.',button('Add plant','add-plant',{icon:'plus'}))+
      `<section class="hero"><div class="hero-copy"><div class="eyebrow dark">YOUR NEXT MILESTONE</div><h2>Local data today.<br>A shared understanding tomorrow.</h2><p>${esc(p().name)} is ${p().report?'publishing an approved operating report.':'ready for its next onboarding step.'} Keep the original evidence, resolve the unknowns, and put trusted numbers in the right hands.</p>${navButton(n[0],n[1],'btn','arrow')}</div>${factoryVisual()}</section>`+
      kpis([['Plants in this demo',num(st.plants.length),'Illustrative subset, not the full Atlas network','factory'],['Publishing reports',num(reporting),'Approved for the stated reporting scope','check'],['Onboarding in progress',num(pending),'Each plant has an explicit next milestone','layers'],['Benchmark exceptions',num(issues),'Observations requiring investigation','flag']])+
      `<div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>Plant onboarding</h2><p>Readiness and reporting across your sample portfolio</p></div><div class="filter">${[['all','All plants'],['pending','In progress'],['reporting','Reporting']].map(([v,l])=>`<button class="${ui.filter===v?'active':''}" data-action="plant-filter" data-value="${v}">${l}</button>`).join('')}</div></div><div style="padding:0 20px 15px"><label class="search">${icon('search')}<input id="plant-search" placeholder="Find a plant…" aria-label="Find a plant"></label></div><div class="table-scroll"><table><thead><tr><th>PLANT / LINE</th><th>STATUS</th><th>READINESS</th><th>INTEGRATION OWNER</th><th></th></tr></thead><tbody>${plantRows()}</tbody></table></div><div class="table-footer"><span>All names and operating records are synthetic.</span>${button('Export workspace','export-workspace',{cls:'secondary small',icon:'down'})}</div></section><section class="panel pad"><div class="flex between"><h2>Latest activity</h2><button class="textbtn" data-nav="activity">View all ${icon('arrow')}</button></div><div style="margin-top:11px">${miniActivity(st.activity.slice(0,5))}</div><div class="hint" style="margin-top:18px">${icon('shield')} Every release needs reviewed mappings, passing checks and two current-version approvals.</div></section></div>`+
      `<div class="panel pad" style="margin-top:20px"><div class="flex between wrap"><div><h3>The business problem we are testing</h3><p class="small muted" style="margin:0">Case brief baseline: 7 months to trusted data · approximately $1.2m integration spend per plant · 9 central IT/operations staff.</p></div><button class="textbtn" data-action="business-context">What this MVP can prove ${icon('arrow')}</button></div></div>`;
  }
  function setup(){const x=p();return title('01 / Plant readiness','Start with the right foundations.','Agree the source, people and reporting scope before connecting the numbers.',plantSelect())+steps()+scope()+
    `<div class="grid-two"><section class="panel pad"><div class="flex between space"><h2>Plant & reporting scope</h2>${button('Edit details','edit-plant',{cls:'secondary small',icon:'edit'})}</div>${[['Plant ID',x.id],['Production line',x.line||'Not set'],['Product population',x.product||'Not set'],['Acquisition close',date(x.acquired)],['Reporting scope','Shift output, scrap and availability']].map(([k,v])=>`<div class="kv"><span>${k}</span><b>${esc(v)}</b></div>`).join('')}<div class="hint" style="margin-top:18px">One line and one comparable output population keep the first report interpretable. Full plant integration is a separate milestone.</div></section><section class="panel pad"><h2>Named owners</h2><p class="page-note">These are illustrative people. Update them to test assignments and reviewer handoffs.</p>${[['Integration owner',x.owners.integration],['Plant operations reviewer',x.owners.operations],['Group data steward',x.owners.steward]].map(([k,v])=>`<div class="kv"><span>${k}</span><b>${esc(v||'Unassigned')}</b></div>`).join('')}<p class="page-note">Plant engineers explain the local process. The data steward owns group comparability. Operations accepts the report’s meaning.</p></section></div>
    <section class="panel pad" style="margin-top:20px"><h2>Readiness checklist</h2><p class="page-note">Record a decision only after the responsible person has confirmed it. Changes invalidate existing reporting acceptance.</p>${[['access','Authorized export access','The plant owner permits this source export to be used for the agreed reporting purpose.',x.owners.integration],['owners','Local and group reviewers are available','Both review responsibilities have named owners and an agreed handoff.',x.owners.operations],['contract','Metric definitions and scope are agreed','Counts, reporting shifts, units, scrap population and planned time are understood.',x.owners.steward]].map(([id,label,detail,owner])=>`<label class="checkline"><input type="checkbox" data-readiness="${id}" ${x.readiness[id]?'checked':''}><span><strong>${label}</strong><small>${detail}</small><small>Owner: ${esc(owner||'Assign an owner')}</small></span></label>`).join('')}<div class="sticky-actions"><span class="small muted">${Object.values(x.readiness).filter(Boolean).length} of 3 prerequisites confirmed</span>${navButton('Continue to source data','data','btn')}</div></section>
    <section class="panel pad" style="margin-top:20px"><div class="flex between"><div><h2>Understand where effort goes</h2><p class="page-note">Log work as it happens. These hours measure activity, not proven cost savings.</p></div>${button('Log effort','log-effort',{cls:'secondary small',icon:'plus'})}</div>${x.effort.length?`<div class="table-scroll"><table><tr><th>ACTIVITY</th><th>PERSON</th><th>HOURS</th><th>NOTE</th></tr>${x.effort.map(e=>`<tr><td>${esc(e.category)}</td><td>${esc(e.person)}</td><td>${num(e.hours,1)}</td><td>${esc(e.note)}</td></tr>`).join('')}</table></div>`:'<p class="small muted">No effort recorded for this plant yet.</p>'}</section>`;}
  function sourceData(){const x=p(),s=x.source;return title('02 / Source intake','Bring the data you already have.','Use a scoped CSV export to start reporting while wider integration continues.',plantSelect())+steps()+scope()+
    `<div class="grid-two"><section class="panel pad"><h2>Add a shift-level export</h2><p class="page-note">Upload your own CSV, or explore the provided sample. Replacing a source archives its current report and clears approvals.</p><div class="dropzone" id="dropzone">${icon('upload')}<strong>Drop your CSV here</strong><span class="small muted">or choose a file from your computer</span>${button('Choose file','choose-file',{cls:'secondary',icon:'file'})}<small>UTF-8 CSV · Up to 2 MB · 10,000 rows · Processed in this browser</small><input type="file" id="source-upload" accept=".csv,text/csv" hidden></div><div class="flex wrap" style="margin-top:15px">${button('Load clean sample','load-sample',{cls:'secondary small',icon:'layers'})}${button('Load error sample','load-broken',{cls:'secondary small',icon:'alert'})}<button class="textbtn right" data-action="download-sample">Download sample ${icon('down')}</button></div>${s?`<div class="source-file"><span class="fileicon">${icon('file')}</span><div><strong>${esc(s.name)}</strong><small>${num(s.rows.length)} rows · ${s.headers.length} columns · Added ${date(s.received)}</small></div>${pill(s.isSample?'Synthetic':'User upload',s.isSample?'neutral':'')}</div>`:''}</section><section class="panel pad"><h2>What makes a useful first export?</h2><ul class="info-list"><li>Plant, line, record and shift identifiers</li><li>Timestamps with an explicit timezone</li><li>One comparable product population</li><li>Total, good and scrap output counts</li><li>Running time and planned production time</li><li>Source definitions or a plant expert who can explain them</li></ul><div class="hint warn">Missing definitions remain questions for the source owner. This version makes no AI calls and does not infer undocumented conversions.</div><div class="sticky-actions">${button('View sample dictionary','dictionary',{cls:'secondary small',icon:'file'})}${navButton('Review mappings','mapping','btn')}</div></section></div>
    <section class="panel" style="margin-top:20px"><div class="panel-head"><div><h2>Original source preview</h2><p>${s?'First '+Math.min(s.rows.length,8)+' of '+num(s.rows.length)+' rows. Calculations use every uploaded row.':'No file received yet.'}</p></div>${s?pill('Original values retained','neutral'):''}</div>${s?`<div class="table-scroll"><table><thead><tr><th>CSV ROW</th>${s.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${s.rows.slice(0,8).map((r,i)=>`<tr><td>${i+2}</td>${s.headers.map(h=>`<td class="mono no-wrap">${esc(r[h])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('A source file starts the workflow.','No rows are generated for a custom upload. Your file becomes the source of truth.')}</section>`;}
  function mapping(){const x=p();if(!x.source)return title('03 / Mapping review','Understand every field.','Connect local terminology to an agreed reporting contract.',plantSelect())+steps()+empty('Add source data first.','Mappings are created from the actual columns in your export.',navButton('Go to source data','data','btn'));
    const unresolved=x.mappings.filter(m=>m.target==='unresolved').length,reviewed=x.mappings.filter(m=>m.reviewed).length;
    const list=x.mappings.filter(m=>ui.mappingFilter==='all'||(ui.mappingFilter==='unresolved'?m.target==='unresolved':!m.reviewed));
    return title('03 / Mapping review','Make the meaning explicit.','Review local definitions, units and source evidence before treating fields as comparable.',plantSelect())+steps()+scope()+
      `<div class="hint space">${icon('link')} <strong>Sample definitions are provided for review.</strong> The sample uses authored source definitions. For your files, edit mappings and record the evidence manually.</div>`+
      `<div class="split3 space"><div class="mini-stat"><strong>${x.mappings.length}</strong><small>Source columns</small></div><div class="mini-stat"><strong>${reviewed} / ${x.mappings.length}</strong><small>Decisions reviewed</small></div><div class="mini-stat"><strong>${unresolved}</strong><small>Unresolved definitions</small></div></div>`+
      `<section class="panel"><div class="panel-head"><div><h2>Field mapping workbench</h2><p>Changing a decision clears validation and current-version approvals.</p></div><div class="flex wrap">${button('Review documented fields','review-documented',{cls:'secondary small',icon:'check'})}${button('Reuse template','templates',{cls:'secondary small',icon:'layers'})}</div></div><div class="flex between wrap" style="padding:0 20px 15px"><div class="filter">${[['all','All fields'],['unresolved','Unresolved'],['unreviewed','Needs review']].map(([v,l])=>`<button data-action="mapping-filter" data-value="${v}" class="${ui.mappingFilter===v?'active':''}">${l}</button>`).join('')}</div>${button('View dictionary','dictionary',{cls:'secondary small',icon:'file'})}</div><div class="table-scroll"><table><thead><tr><th>SOURCE FIELD / EXAMPLE</th><th>REPORTING FIELD</th><th>SOURCE UNIT / CONVERSION</th><th>DECISION</th><th></th></tr></thead><tbody>${list.map(m=>{const target=C.FIELDS.find(f=>f.id===m.target);return `<tr><td><div class="mapping-source">${esc(m.source)}</div><div class="mapping-def">${esc(x.source.rows.slice(0,2).map(r=>r[m.source]).join(' · '))}</div></td><td>${esc(target?.label||(m.target==='excluded'?'Excluded from scope':'Needs clarification'))}<div class="mapping-def">${esc(m.definition||'Document the local meaning.')}</div></td><td><span class="mono">${esc(m.unit||'Not recorded')}</span><div class="mapping-def">${m.transform==='seconds_to_minutes'?'Divide seconds by 60':m.transform==='hours_to_minutes'?'Multiply hours by 60':'Keep source value'}</div></td><td>${m.target==='unresolved'?pill('Unresolved','warn'):m.reviewed?pill('Reviewed'):pill('Needs review','neutral')}</td><td>${button(m.target==='unresolved'?'Resolve':'Inspect','edit-mapping',{data:m.source,cls:'secondary small',icon:'edit'})}</td></tr>`;}).join('')||'<tr><td colspan="5">No fields match this filter.</td></tr>'}</tbody></table></div><div class="table-footer"><span>Exclusions require a reason. Unsupported conversions stay unresolved.</span>${navButton('Run validation','validation','btn small')}</div></section>`;
  }
  function validation(){const x=p(),v=x.validation,current=v&&v.fingerprint===C.fingerprint(x);return title('04 / Data validation','Trust is a set of checks.','Validate the actual source records against the reviewed reporting contract.',plantSelect())+steps()+scope()+
    `<div class="readiness-banner"><div><strong>${current?(v.pass?'All checks passed for this version.':'Some checks need your attention.'):'This source version has not been validated.'}</strong><small>${current?v.checks.filter(c=>c.pass).length+' of '+v.checks.length+' checks passed · '+num(v.records)+' records checked':'Resolve field decisions and run the checks. No failed rows are silently dropped.'}</small></div>${button('Run validation','run-validation',{icon:'shield',disabled:!x.source})}</div><div class="grid-main"><section class="panel pad"><h2>Release checks</h2>${current?v.checks.map(c=>`<div class="validation-item"><span class="rule-icon ${c.pass?'':'fail'}">${c.pass?'✓':'!'}</span><div><strong>${esc(c.title)}</strong><small>${esc(c.detail)}</small>${c.rows.length?`<small>Displayed affected CSV rows: ${c.rows.join(', ')}${c.rows.length===20?' (first 20)':''}</small>`:''}</div></div>`).join(''):empty('Ready when you are.','Validation checks source completeness, reviewed definitions, dimensions, row values, scope, duplicates and timestamps.',button('Validate current version','run-validation',{disabled:!x.source,icon:'shield'}))}<div class="sticky-actions">${navButton('Review mappings','mapping','textbtn','chevron')}${navButton('Continue to approvals','approvals','btn')}</div></section><section class="panel pad"><h2>Validation scope</h2>${[['Source',x.source?.name||'Not received'],['Rows in scope',x.source?num(x.source.rows.length):'—'],['Mapping version','Revision '+x.revision],['Reporting population',x.product||'Not set'],['Approval status',current&&v.pass?'May request review':'Blocked']].map(([k,val])=>`<div class="report-line"><span>${k}</span><b>${esc(val)}</b></div>`).join('')}<div class="hint warn" style="margin-top:20px">Passing checks establishes consistency with the supplied definitions. Plant and group owners still need to verify that those definitions reflect the physical process.</div>${current?`<div style="margin-top:18px">${button('Download validation record','export-validation',{cls:'secondary small',icon:'down'})}</div>`:''}</section></div>`;}
  function approvals(){const x=p(),valid=x.validation?.pass&&x.validation.fingerprint===C.fingerprint(x);return title('05 / Acceptance & publication','Put accountable owners behind the numbers.','Review and publish one exact source-and-mapping version.',plantSelect())+steps()+scope()+
    `<div class="hint warn space">Demo roles simulate the handoff between people. This browser MVP does not authenticate reviewers or provide a tamper-proof audit log.</div><div class="grid-main"><section class="panel pad"><div class="flex between"><h2>Reporting acceptance</h2>${pill(x.report?'Published':valid?'Ready for review':'Validation required',x.report?'':valid?'warn':'neutral')}</div>${[['steward','Group data steward',x.owners.steward,'Data steward','Definitions, units, exclusions and cross-plant meaning have been reviewed.'],['operations','Plant operations owner',x.owners.operations,'Plant operations','Source totals and the report reflect the agreed line, product population and shifts.']].map(([id,label,person,role,attest])=>{const a=x.approvals[id];return `<div class="approval-card ${a?'approved':''}"><div class="flex"><span class="avatar">${esc((person||'?').split(' ').map(s=>s[0]).join('').slice(0,2))}</span><div><h3>${label}</h3><span class="tiny muted">${esc(person||'Assign reviewer in Plant setup')}</span></div><span class="right">${pill(a?'Approved':'Awaiting review',a?'':'neutral')}</span></div>${a?`<p class="page-note">Accepted by ${esc(a.person)} · ${date(a.at)} at ${time(a.at)}</p>`:`<label class="checkline"><input type="checkbox" id="attest-${id}" ${!valid||st.role!==role?'disabled':''}><span>${attest}</span></label>${button('Approve as '+label.toLowerCase(),'approve-'+id,{cls:'secondary small',disabled:!valid||st.role!==role,icon:'check'})}<p class="page-note">${st.role===role?'Select the review statement before approving.':'Choose the '+role+' demo role in the top bar to review.'}</p>`}</div>`;}).join('')}<div class="sticky-actions"><span class="small muted">${x.report?'A current report is available.':Object.values(x.approvals).filter(Boolean).length+' of 2 approvals recorded'}</span>${button(x.report?'Open published report':'Publish operating report',x.report?'view-report':'publish',{icon:'arrow',disabled:!x.report&&(!valid||!x.approvals.steward||!x.approvals.operations||st.role!=='Integration lead')})}</div>${!x.report&&st.role!=='Integration lead'?'<p class="page-note">The Integration lead demo role publishes after both reviews.</p>':''}</section><section class="panel pad"><h2>What is being accepted?</h2>${[['Plant and line',x.name+' / '+x.line],['Source file',x.source?.name||'Not received'],['Source records',x.source?num(x.source.rows.length):'—'],['Product population',x.product||'Not set'],['Revision',String(x.revision)],['Metrics','Output · scrap · availability']].map(([k,v])=>`<div class="report-line"><span>${k}</span><b>${esc(v)}</b></div>`).join('')}<div class="hint" style="margin-top:20px">Any relevant source, scope or mapping change clears both approvals. The previous report is retained as history.</div><p class="page-note">This acceptance is scoped to the uploaded window. A real production release also needs source authorization, parallel reporting, security review and operational handover.</p></section></div>`;}
  function performance(){const x=p(),r=x.report;if(!r)return title('Operating visibility','A report worth acting on.','Published numbers retain their source, scope and acceptance history.',plantSelect())+scope()+empty('No current approved report.','Complete mapping review, validation and both approvals. If the source changed, the prior report is historical.',navButton('Open acceptance workflow','approvals','btn'))+(x.history.length?`<div class="hint warn">${x.history.length} historical report(s) retained. They are not current operating evidence.</div>`:'');
    const m=r.metrics,ds=C.deviations(x),maximum=Math.max(...m.series.map(s=>s.total),1);
    return title('Operating visibility','From trusted data to a useful decision.','Inspect the approved reporting window, then compare only against a compatible benchmark.',`<div class="flex wrap">${plantSelect()}${button('Export report','export-report',{cls:'secondary',icon:'down'})}</div>`)+scope()+
      `<div class="flex between space wrap"><div class="badges">${pill('Approved report')}${pill('One line · one product','neutral')}${pill(x.source?.isSample?'Synthetic sample':'User-uploaded data','neutral')}</div><span class="tiny muted">Window: ${date(m.from)} – ${date(m.to)} · ${m.rows} records</span></div>`+
      kpis([['Total output',num(m.total),'All '+m.rows+' source records included','factory'],['Scrap rate',pct(m.scrapRate),num(m.scrap)+' scrap / '+num(m.total)+' total units','flag'],['Availability',pct(m.availability),num(m.runMinutes,1)+' / '+num(m.plannedMinutes,1)+' minutes · not OEE','clock'],['Source coverage','100%','All uploaded records passed required checks','shield']])+
      `<div class="grid-main"><section class="panel pad"><div class="flex between"><div><h2>Shift output</h2><p class="page-note">${m.series.length>12?'First 12 records shown; totals include every record.':'Actual counts from this approved source window.'}</p></div>${pill(m.shifts+' shifts','neutral')}</div><div class="chart" role="img" aria-label="Good and scrap output by source record">${m.series.slice(0,12).map(s=>`<div class="chart-col"><div class="bar" style="height:${s.good/maximum*100}%"><span>${num(s.good)}</span></div><div class="bar scrap" style="height:${s.scrap/maximum*100}%"><span>${num(s.scrap)}</span></div><label>${esc(s.shift)}</label></div>`).join('')}</div><div class="legend"><span><i></i>Good output</span><span><i class="scrap"></i>Scrap output</span></div><div class="table-scroll" style="margin-top:22px"><table><tr><th>SHIFT</th><th>TOTAL</th><th>GOOD</th><th>SCRAP</th><th>AVAILABILITY</th></tr>${m.series.slice(0,12).map(s=>`<tr><td>${esc(s.shift)}</td><td>${num(s.total)}</td><td>${num(s.good)}</td><td>${num(s.scrap)}</td><td>${pct(s.availability)}</td></tr>`).join('')}</table></div></section><section class="panel pad"><div class="flex between"><h2>Benchmark exceptions</h2>${button('Set benchmark','benchmark',{cls:'secondary small',icon:'edit'})}</div><p class="page-note">Compare the same population and reporting window. A deviation is a prompt to investigate.</p>${!x.benchmark.confirmed?empty('Confirm a comparable benchmark.','Add the source and reporting window before interpreting performance gaps.',button('Add benchmark','benchmark',{cls:'secondary small'})):ds.length?ds.map(d=>`<div class="deviation"><strong>${esc(d.label)}</strong><div class="metric-pair"><div><strong>${num(d.actual,d.unit==='%'?1:0)}${d.unit==='%'?'%':''}</strong><small>ACTUAL</small></div><div><strong>${num(d.target,d.unit==='%'?1:0)}${d.unit==='%'?'%':''}</strong><small>${d.key==='scrap'?'MAXIMUM':'BENCHMARK'}</small></div></div><p>${esc(d.description)}</p>${button('Create investigation','new-case',{data:d.key,cls:'secondary small',icon:'flag'})}</div>`).join(''):'<div class="hint">No exceptions against the supplied benchmark. This does not establish that all operating risks are absent.</div>'}${x.benchmark.confirmed?`<p class="page-note">Benchmark: ${esc(x.benchmark.period)}<br>Evidence: ${esc(x.benchmark.evidence)}</p>`:''}</section></div>
      <section class="panel pad" style="margin-top:20px"><div class="flex between wrap"><h2>Evidence behind this report</h2>${button('Save mapping template','save-template',{cls:'secondary small',icon:'layers'})}</div><div class="grid-two" style="margin-top:12px"><div>${[['Source file',r.sourceName],['Source received',date(r.sourceReceived)],['Source reporting window',date(m.from)+' – '+date(m.to)],['Reporting scope',r.scope.line+' / '+r.scope.product]].map(([k,v])=>`<div class="report-line"><span>${k}</span><b>${esc(v)}</b></div>`).join('')}</div><div>${[['Published',date(r.at)+' at '+time(r.at)],['Data steward',r.approvals.steward.person],['Operations reviewer',r.approvals.operations.person],['Accepted revision',String(r.revision)]].map(([k,v])=>`<div class="report-line"><span>${k}</span><b>${esc(v)}</b></div>`).join('')}</div></div><p class="page-note">Source freshness and reporting-period recency are different: a newly uploaded file can contain older shifts. No extrapolation to the rest of the plant is implied.</p></section>`;
  }
  function investigations(){const list=st.investigations.filter(c=>ui.caseFilter==='all'||(ui.caseFilter==='open'?c.status!=='Resolved':c.status==='Resolved'));return title('Business follow-through','Turn a signal into an owned investigation.','Keep the observation, supporting report, responsible person and resolution together.',button('View operating report','view-report',{cls:'secondary',icon:'chart'}))+
    kpis([['Open investigations',num(st.investigations.filter(c=>c.status!=='Resolved').length),'Require an owner and next action','flag'],['Resolved cases',num(st.investigations.filter(c=>c.status==='Resolved').length),'Closure requires a resolution record','check'],['Plants with cases',num(new Set(st.investigations.map(c=>c.plant)).size),'Scoped to the originating report','factory'],['Automatic diagnoses','0','Every causal explanation needs evidence','shield']])+
    `<div class="flex between space wrap"><h2>Investigation register</h2><div class="filter">${[['all','All cases'],['open','Open'],['resolved','Resolved']].map(([v,l])=>`<button data-action="case-filter" data-value="${v}" class="${ui.caseFilter===v?'active':''}">${l}</button>`).join('')}</div></div>${list.length?list.map(c=>`<section class="case-card"><div class="flex between wrap"><div class="flex">${icon('flag')}<h3 style="margin:0">${esc(c.title)}</h3>${pill(esc(c.status),c.status==='Resolved'?'':'warn')}</div>${button('Update case','edit-case',{data:c.id,cls:'secondary small',icon:'edit'})}</div><p>${esc(c.observation)}</p><div class="case-meta"><span>Plant: ${esc(st.plants.find(x=>x.id===c.plant)?.name||c.plant)}</span><span>Owner: ${esc(c.owner)}</span><span>Opened: ${date(c.created)}</span><span>Report: ${esc(c.reportId)}</span></div>${c.note?`<div class="hint" style="margin-top:15px"><strong>${c.status==='Resolved'?'Resolution':'Next action / findings'}</strong><br>${esc(c.note)}</div>`:''}<p class="page-note">Evidence is pinned to the originating report. ${st.plants.find(x=>x.id===c.plant)?.report?.id===c.reportId?'That report is current.':'That report is now historical; re-check against current data.'}</p></section>`).join(''):`<section class="panel">${empty('No investigations in this view.','Publish a report, confirm its comparable benchmark, and create an investigation from a deviation.',button('Open sample report','sample-report',{cls:'secondary',icon:'chart'}))}</section>`}`;}
  function activity(){const items=st.activity.filter(a=>ui.activityScope==='all'||a.plant===ui.activityScope);return title('Activity & evidence','Keep the decisions connected.','Review the local workflow history and export evidence for a product review.',button('Export workspace','export-workspace',{cls:'secondary',icon:'down'}))+
    `<div class="hint space">This is a browser-local activity record for the prototype. It is editable through browser storage and is not an enterprise audit service.</div><section class="panel"><div class="panel-head"><h2>Workspace history</h2><select id="activity-scope" class="select-plain" aria-label="Activity plant filter"><option value="all">All plants</option>${st.plants.map(x=>`<option value="${esc(x.id)}" ${ui.activityScope===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="table-scroll"><table><tr><th>WHEN</th><th>PLANT</th><th>ACTOR / DEMO ROLE</th><th>DECISION</th><th>DETAIL</th></tr>${items.map(a=>`<tr><td class="tiny no-wrap">${date(a.at)}<br><span class="muted">${time(a.at)}</span></td><td>${esc(a.plant)}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td><td class="tiny muted">${esc(a.detail)}</td></tr>`).join('')||'<tr><td colspan="5">No activity for this plant.</td></tr>'}</table></div><div class="table-footer"><span>${items.length} recorded actions · latest 500 retained</span>${button('Reset demo','reset-demo',{cls:'secondary small',icon:'refresh'})}</div></section>`;}

  // Dialogs and event handlers are defined below. All user-supplied strings are escaped.
  function modal(heading,body,footer=''){const d=document.getElementById('dialog');d.innerHTML=`<div class="dialog-head"><div><div class="eyebrow">ATLAS WORKSPACE</div><h2>${heading}</h2></div><button class="iconbtn" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}<div id="form-error" class="error-text" role="alert"></div></div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;if(!d.open)d.showModal();}
  function close(){document.getElementById('dialog').close();}
  const cancel=()=>button('Cancel','close-dialog',{cls:'secondary'});
  const submit=label=>`<button type="submit" form="modal-form" class="btn">${label}</button>`;
  function field(label,name,value='',type='text',extra=''){return `<div class="form-field"><label for="form-${name}">${label}</label><input id="form-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
  function area(label,name,value='',extra=''){return `<div class="form-field full"><label for="form-${name}">${label}</label><textarea id="form-${name}" name="${name}" ${extra}>${esc(value)}</textarea></div>`;}
  const options=(values,current)=>values.map(v=>`<option value="${esc(Array.isArray(v)?v[0]:v)}" ${(Array.isArray(v)?v[0]:v)===current?'selected':''}>${esc(Array.isArray(v)?v[1]:v)}</option>`).join('');
  function selectField(label,name,values,current){return `<div class="form-field"><label for="form-${name}">${label}</label><select id="form-${name}" name="${name}">${options(values,current)}</select></div>`;}
  function error(message){const e=document.getElementById('form-error');if(e)e.textContent=message;else toast(message);}
  function download(name,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function csvCell(value){let s=String(value??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
  function sampleForPlant(plant,broken=false){const parsed=C.parseCSV(C.SAMPLE_CSV);parsed.rows.forEach(r=>{r.plant_id=plant.id;r.asset_id=plant.line||'SYN-LINE-A';r.product_family=plant.product||'SYN-Product-A';});if(broken)parsed.rows[0].GoodQty='600';return [parsed.headers,...parsed.rows.map(r=>parsed.headers.map(h=>r[h]))].map(r=>r.map(csvCell).join(',')).join('\n');}
  async function receiveFile(file){const plant=p();try{if(file.size>2*1024*1024)throw new Error('Choose a CSV up to 2 MB.');if(!/\.csv$/i.test(file.name))throw new Error('This MVP accepts CSV exports. Save your spreadsheet as CSV first.');const text=await file.text();C.loadSource(plant,text,file.name,false);record('Source export uploaded',file.name+' · '+plant.source.rows.length+' records. Current approvals cleared.',plant);render();toast('File received for '+plant.name+'. Review its definitions next.');}catch(e){toast(e.message);}}
  function showPlantForm(isNew){const x=isNew?{id:'',name:'',line:'',product:'',acquired:'',owners:{integration:'',operations:'',steward:''}}:p();modal(isNew?'Add a plant':'Plant scope & owners',`<form id="modal-form" data-form="${isNew?'add-plant':'edit-plant'}"><div class="form-grid">${field('Plant name','name',x.name,'text','required maxlength="80"')}${field('Plant ID','id',x.id,'text',isNew?'required pattern="[A-Za-z0-9_-]{2,32}"':'readonly')}${field('Production line ID','line',x.line,'text','required maxlength="60"')}${field('Comparable product family','product',x.product,'text','required maxlength="80"')}${field('Acquisition close date','acquired',x.acquired,'date','required')}${field('Integration owner','integration',x.owners.integration,'text','required maxlength="80"')}${field('Plant operations reviewer','operations',x.owners.operations,'text','required maxlength="80"')}${field('Group data steward','steward',x.owners.steward,'text','required maxlength="80"')}</div></form><p class="page-note">IDs must match the source records. Updating scope or accountable owners clears prior validation and approvals.</p>`,cancel()+submit(isNew?'Create plant':'Save details'));}
  function showMapping(source){const m=p().mappings.find(x=>x.source===source);if(!m)return;modal('Review '+esc(source),`<form id="modal-form" data-form="mapping" data-source="${esc(source)}"><div class="hint space">Source examples: <span class="mono">${esc(p().source.rows.slice(0,3).map(r=>r[source]).join(' · '))}</span></div><div class="form-grid">${selectField('Reporting field','target',[['unresolved','Unresolved — ask the source owner'],...C.FIELDS.map(f=>[f.id,f.label]),['excluded','Exclude from this reporting scope']],m.target)}${selectField('Source unit','unit',['','text','UTC timestamp','count','s','min','h','cycles','kWh'],m.unit)}${selectField('Transformation','transform',[['identity','Keep value'],['seconds_to_minutes','Seconds → minutes (÷ 60)'],['hours_to_minutes','Hours → minutes (× 60)']],m.transform)}${field('Source reference / document location','evidence',m.evidence,'text','maxlength="240"')}${area('Local field definition','definition',m.definition,'maxlength="1000"')}${area('Exclusion reason (required if excluded)','reason',m.reason,'maxlength="1000"')}</div><label class="checkline"><input type="checkbox" name="reviewed" ${m.reviewed?'checked':''}><span>I have checked this decision against the source definition or recorded the unresolved question.</span></label></form><p class="page-note">A source reference records where a definition came from. Its presence alone does not prove the definition is correct.</p>`,cancel()+submit('Save field decision'));}
  function showBulkReview(){const eligible=p().mappings.filter(m=>m.target!=='unresolved'&&(m.target==='excluded'?m.reason.trim().length>=10:m.definition.trim().length>=10&&m.evidence.trim().length>=5));modal('Review documented field decisions',`<form id="modal-form" data-form="bulk-review"><div class="review-list">${eligible.map(m=>`<div><code>${esc(m.source)} → ${esc(m.target)}</code><p>${esc(m.target==='excluded'?m.reason:m.definition)}<br>Evidence: ${esc(m.evidence)}</p></div>`).join('')||'<p class="small muted">Document field definitions and evidence before using bulk review.</p>'}</div><label class="checkline"><input type="checkbox" name="confirm" required><span>I reviewed the ${eligible.length} documented decisions shown above. Unresolved fields remain blocked.</span></label></form>`,cancel()+submit('Confirm reviewed decisions'));}
  function showBenchmark(){if(!p().report){toast('Publish a report before setting its benchmark.');return;}const b=p().benchmark;modal('Set a comparable benchmark',`<form id="modal-form" data-form="benchmark"><div class="hint space">This benchmark applies to the exact uploaded reporting window: ${date(p().report.metrics.from)} – ${date(p().report.metrics.to)}, ${p().report.metrics.rows} records, ${esc(p().line)}, ${esc(p().product)}.</div><div class="form-grid">${field('Total output target for this entire window','output',b.output,'number','required min="1" step="1"')}${field('Maximum scrap rate (%)','scrap',b.scrap,'number','required min="0" max="100" step="0.1"')}${field('Availability target (%)','availability',b.availability,'number','required min="0" max="100" step="0.1"')}${field('Reporting window / period definition','period',b.period,'text','required maxlength="160"')}${area('Benchmark evidence / acquisition-plan reference','evidence',b.evidence,'required minlength="10" maxlength="500"')}</div><label class="checkline"><input type="checkbox" name="confirm" required><span>I confirm that this benchmark uses the same product, line, metric definitions and reporting window. Differences have been reconciled.</span></label></form><p class="page-note">Targets are supplied assumptions, not predictions. Exceptions do not establish a root cause or financial loss.</p>`,cancel()+submit('Save comparable benchmark'));}
  function showNewCase(key){const d=C.deviations(p()).find(d=>d.key===key);if(!d)return;const existing=st.investigations.find(c=>c.reportId===p().report.id&&c.key===key&&c.status!=='Resolved');if(existing){go('investigations');toast('An open investigation already tracks this exception.');return;}modal('Create an investigation',`<form id="modal-form" data-form="new-case" data-key="${esc(key)}"><div class="hint warn space"><strong>${esc(d.label)}</strong><br>${esc(d.description)}</div><div class="form-grid">${field('Investigation title','title',d.label,'text','required maxlength="120"')}${field('Responsible person','owner',p().owners.operations,'text','required maxlength="80"')}${area('First action or question to investigate','note','','required minlength="10" maxlength="1500"')}</div></form>`,cancel()+submit('Create investigation'));}
  function showCase(id){const c=st.investigations.find(c=>c.id===id);if(!c)return;modal('Update investigation',`<form id="modal-form" data-form="edit-case" data-id="${esc(id)}"><div class="form-grid">${field('Responsible person','owner',c.owner,'text','required maxlength="80"')}${selectField('Status','status',['Open','Investigating','Action assigned','Resolved'],c.status)}${area('Next action / findings / resolution evidence','note',c.note,'required minlength="10" maxlength="2000"')}</div></form><p class="page-note">A resolved case needs a documented action or finding. Closure does not automatically demonstrate recovered production or savings.</p>`,cancel()+submit('Save investigation'));}
  function showTemplates(){modal('Reusable mapping templates',st.templates.length?st.templates.map(t=>`<div class="approval-card"><h3>${esc(t.name)}</h3><p class="page-note">${esc(t.plant)} · ${t.mappings.length} fields · Saved ${date(t.at)}</p>${button('Apply as an unreviewed draft','apply-template',{data:t.id,cls:'secondary small'})}</div>`).join(''):'<p class="small muted">Publish an approved report, then save its mapping as a reusable template from Operating reports.</p>');}
  function help(){modal('About this interactive MVP',`<p class="small">Atlas Onboard demonstrates a path from local plant records to reviewed operating reporting and owned investigations.</p><ul class="info-list"><li>All preloaded plants, people, records and benchmarks are synthetic.</li><li>Custom CSV uploads are processed locally and drive the calculations.</li><li>Sample definitions are authored; model-assisted interpretation is planned.</li><li>Demo role selection simulates handoffs; it is not authentication.</li><li>Data and decisions persist in this browser’s local storage.</li><li>No machine connection, ERP write, or external data transmission occurs.</li></ul><div class="flex wrap">${button('Demo walkthrough','guide',{cls:'secondary'})}${button('Export workspace','export-workspace',{cls:'secondary',icon:'down'})}</div>`);}
  const actions={
    'close-dialog':close,'help':help,'ai-info':()=>modal('Assistant capabilities',`<p class="small">Available now: source review, validation, human acceptance and operating reports. Model-assisted interpretation and clarification are planned capabilities.</p><div class="hint space">Sample field definitions are authored examples. Custom data requires manual mappings and documented evidence.</div><p class="page-note">A future AI service can propose mappings and clarification questions. The deterministic validation and human acceptance gates will still apply.</p>`),
    'add-plant':()=>showPlantForm(true),'edit-plant':()=>showPlantForm(false),'edit-mapping':showMapping,
    'open-plant':id=>{const plant=st.plants.find(x=>x.id===id);changePlant(id,plant.report?'performance':next(plant)[1]);},
    'plant-filter':v=>{ui.filter=v;render();},'mapping-filter':v=>{ui.mappingFilter=v;render();},'case-filter':v=>{ui.caseFilter=v;render();},
    'choose-file':()=>document.getElementById('source-upload').click(),
    'load-sample':()=>loadDemo(false),'load-broken':()=>loadDemo(true),
    'download-sample':()=>download('atlas-'+p().id+'-sample.csv',sampleForPlant(p()),'text/csv'),
    'dictionary':()=>modal('Synthetic source dictionary',`<p class="small muted">These definitions describe the supplied sample only. A custom upload needs its own source-owner confirmation.</p><div class="review-list">${Object.entries(C.SAMPLE_DEFS).map(([source,d])=>`<div><code>${esc(source)} → ${esc(d[0])} (${esc(d[1])})</code><p>${esc(d[2])}</p></div>`).join('')}<div><code>CycleCount → unresolved</code><p>No verified pieces-per-cycle conversion is supplied. Independently defined TotalQty can supply output without using CycleCount.</p></div></div>`),
    'review-documented':showBulkReview,
    'run-validation':()=>{const x=p();x.validation=C.validate(x);if(!x.validation.pass)x.approvals={steward:null,operations:null};record('Validation completed',x.validation.checks.filter(c=>c.pass).length+'/'+x.validation.checks.length+' checks passed for revision '+x.revision+'.');render();toast(x.validation.pass?'Validation passed. Request accountable reviews.':'Validation found issues. Inspect the failed checks.');},
    'approve-steward':()=>review('steward','Data steward'),'approve-operations':()=>review('operations','Plant operations'),
    'publish':()=>{if(st.role!=='Integration lead')throw new Error('Choose the Integration lead demo role to publish.');const report=C.publish(p());record('Operating report published',report.metrics.rows+' records; accepted revision '+report.revision+'.');go('performance');toast('Approved report published for this source window.');},
    'view-report':()=>go('performance'),'sample-report':()=>changePlant('SYN-P08','performance'),
    'benchmark':showBenchmark,'new-case':showNewCase,'edit-case':showCase,
    'export-workspace':()=>download('atlas-workspace.json',JSON.stringify({exportedAt:new Date().toISOString(),mode:'browser-local; Prototype mode; demo roles',workspace:st},null,2)),
    'export-validation':()=>download('atlas-'+p().id+'-validation.json',JSON.stringify(p().validation,null,2)),
    'export-report':()=>{if(!p().report)return;download('atlas-'+p().id+'-report.json',JSON.stringify({disclosure:'Browser-local MVP; demo approvals; synthetic when using samples.',report:p().report,benchmark:p().benchmark},null,2));},
    'templates':showTemplates,'save-template':()=>{const x=p();if(!x.report)throw new Error('An approved report is required.');const t={id:C.uid('template'),name:x.name+' · reporting v1',plant:x.id,at:new Date().toISOString(),mappings:C.copy(x.mappings)};st.templates.push(t);record('Mapping template saved',t.name);toast('Template saved. Reuse starts as an unreviewed draft.');},
    'apply-template':id=>{const t=st.templates.find(t=>t.id===id);if(!t||!p().source)return;const headers=p().source.headers;if(t.mappings.length!==headers.length||!headers.every(h=>t.mappings.some(m=>m.source===h)))throw new Error('Source columns differ. This template is incompatible with the current export.');C.invalidate(p());p().mappings=headers.map(h=>({...C.copy(t.mappings.find(m=>m.source===h)),reviewed:false,evidence:''}));record('Template applied as draft','Prior evidence was cleared. Confirm source definitions for this plant.');close();render();toast('Draft applied. Add local evidence and review each decision.');},
    'log-effort':()=>modal('Log onboarding effort',`<form id="modal-form" data-form="effort"><div class="form-grid">${selectField('Activity','category',['Access','Interpretation','Validation','Review','Rework','Other'],'Interpretation')}${field('Hours of active work','hours','','number','required min="0.1" max="168" step="0.1"')}${field('Person','person',p().owners.integration,'text','required maxlength="80"')}${field('Brief work note','note','','text','required minlength="5" maxlength="300"')}</div></form><p class="page-note">Effort is not elapsed lead time. Overlapping activities must not be added together as calendar delay.</p>`,cancel()+submit('Record effort')),
    'business-context':()=>modal('What the MVP can prove',`<div class="hint space">The case supplies an average of 7 months to trusted data and roughly $1.2m integration spend per plant. It does not break down activities, avoidable costs or recoverable production losses.</div><ul class="info-list"><li>Measure the first accepted report separately from full integration.</li><li>Compare engineering hours and rework on equivalent scope.</li><li>Record when a credible exception reaches an accountable owner.</li><li>Separate released capacity from cash savings.</li><li>Validate the critical path before claiming that AI reduces onboarding time.</li></ul><p class="page-note">A report from three synthetic shifts demonstrates mechanics. It does not prove real-world ROI or a seven-month reduction.</p>`),
    'guide':()=>{close();modal('A five-minute product walkthrough',`<ol class="info-list"><li>Choose North works and confirm the three Plant setup prerequisites.</li><li>Its sample export is already loaded. Open Mapping review.</li><li>Review documented fields, then resolve CycleCount by excluding it with a reason.</li><li>Run validation. All required checks should pass.</li><li>Use the Data steward and Plant operations demo roles to record reviews.</li><li>Return to Integration lead, publish, and set a comparable benchmark.</li><li>Create and update an investigation from a benchmark exception.</li></ol><div class="hint">For the error path, load the error sample from Source data. Validation will expose an unreconciled output row.</div>`,button('Start with North works','start-guide',{icon:'arrow'}));},
    'start-guide':()=>{close();changePlant('SYN-P12','setup');},
    'reset-demo':()=>modal('Restore the sample workspace?',`<p class="small">This replaces plants, uploaded files, mappings, cases and activity stored by this MVP in this browser. Download a workspace export first if you want to keep them.</p>`,cancel()+button('Restore sample workspace','confirm-reset',{cls:'danger'})),
    'confirm-reset':()=>{st=C.initial();st.templates=[];close();save();render();toast('Sample workspace restored.');}
  };
  function loadDemo(broken){const x=p();C.loadSource(x,sampleForPlant(x,broken),broken?'sample-with-output-error.csv':'sample-shift-export.csv',true);record('Sample source loaded',broken?'Synthetic output reconciliation error included.':'Clean synthetic source; field review still required.');render();toast(broken?'Error sample loaded. Review mappings, then validate.':'Sample loaded. Definitions still need human review.');}
  function review(id,role){if(st.role!==role)throw new Error('Choose the '+role+' demo role first.');if(!document.getElementById('attest-'+id)?.checked)throw new Error('Confirm the review statement before approving.');C.approve(p(),id,p().owners[id==='steward'?'steward':'operations']);record(role+' review accepted','Accepted source and mapping revision '+p().revision+'.');render();toast(role+' approval recorded.');}
  document.addEventListener('click',e=>{const a=e.target.closest('[data-action]'),n=e.target.closest('[data-nav]');try{if(a&&!a.disabled){const fn=actions[a.dataset.action];if(fn)fn(a.dataset.value);}else if(n&&!n.disabled)go(n.dataset.nav);}catch(err){if(document.getElementById('dialog').open)error(err.message);else toast(err.message);}});
  document.addEventListener('change',e=>{const el=e.target;try{
    if(el.id==='plant-select')changePlant(el.value);
    else if(el.id==='role-select'){st.role=el.value;save();render();}
    else if(el.id==='source-upload'&&el.files[0])receiveFile(el.files[0]);
    else if(el.dataset.readiness){C.invalidate(p());p().readiness[el.dataset.readiness]=el.checked;record('Readiness decision updated',el.dataset.readiness+' '+(el.checked?'confirmed':'reopened')+'. Prior acceptance cleared.');render();}
    else if(el.id==='activity-scope'){ui.activityScope=el.value;render();}
  }catch(err){toast(err.message);}});
  document.addEventListener('input',e=>{if(e.target.id==='plant-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('[data-plant-row]').forEach(row=>{row.hidden=!row.dataset.search.includes(q);});}});
  document.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const d=Object.fromEntries(new FormData(form));try{
    if(form.dataset.form==='add-plant'||form.dataset.form==='edit-plant'){
      const owners={integration:d.integration.trim(),operations:d.operations.trim(),steward:d.steward.trim()};
      if(!d.name.trim()||!d.line.trim()||!d.product.trim()||!Object.values(owners).every(Boolean))throw new Error('Complete scope and owner names.');
      if(form.dataset.form==='add-plant'){if(st.plants.some(x=>x.id===d.id))throw new Error('That plant ID already exists.');const x=C.createPlant({...d,name:d.name.trim(),line:d.line.trim(),product:d.product.trim(),owners});st.plants.push(x);st.selected=x.id;record('Plant workspace created',x.name+' · source and reporting acceptance pending.');st.view='setup';}
      else {C.invalidate(p());Object.assign(p(),{name:d.name.trim(),line:d.line.trim(),product:d.product.trim(),acquired:d.acquired,owners});record('Plant scope updated','Scope or accountable owners changed. Prior acceptance cleared.');}
    } else if(form.dataset.form==='mapping'){
      if(d.target==='excluded'&&d.reason.trim().length<10)throw new Error('Record an exclusion reason of at least 10 characters.');
      if(d.target!=='excluded'&&d.target!=='unresolved'&&(d.definition.trim().length<10||d.evidence.trim().length<5))throw new Error('Add a clear local definition and a source reference.');
      C.applyMapping(p(),form.dataset.source,{...d,reviewed:!!d.reviewed});record('Field decision updated',form.dataset.source+' → '+d.target+'. Prior acceptance cleared.');
    } else if(form.dataset.form==='bulk-review'){
      if(!d.confirm)throw new Error('Confirm the review statement.');const eligible=p().mappings.filter(m=>m.target!=='unresolved'&&(m.target==='excluded'?m.reason.trim().length>=10:m.definition.trim().length>=10&&m.evidence.trim().length>=5));
      if(!eligible.length)throw new Error('No documented decisions are ready for review.');C.invalidate(p());eligible.forEach(m=>m.reviewed=true);record('Documented field decisions reviewed',eligible.length+' decisions confirmed; unresolved fields stay blocked.');
    } else if(form.dataset.form==='benchmark'){
      if(!d.confirm)throw new Error('Confirm the comparison scope.');const b={output:Number(d.output),scrap:Number(d.scrap),availability:Number(d.availability),period:d.period.trim(),evidence:d.evidence.trim(),confirmed:true,reportFingerprint:p().report.fingerprint};
      if(!(b.output>0)||![b.scrap,b.availability].every(v=>Number.isFinite(v)&&v>=0&&v<=100)||b.evidence.length<10||!b.period)throw new Error('Supply valid targets, period and benchmark evidence.');p().benchmark=b;record('Comparable benchmark recorded',b.period+'; evidence: '+b.evidence);
    } else if(form.dataset.form==='new-case'){
      const deviation=C.deviations(p()).find(x=>x.key===form.dataset.key);if(!deviation)throw new Error('This exception is no longer current.');if(d.note.trim().length<10)throw new Error('Describe a concrete first action.');
      const c={id:C.uid('case'),plant:p().id,key:deviation.key,reportId:p().report.id,title:d.title.trim(),owner:d.owner.trim(),status:'Open',created:new Date().toISOString(),note:d.note.trim(),observation:deviation.label+': actual '+num(deviation.actual,1)+' '+deviation.unit+'; benchmark '+num(deviation.target,1)+' '+deviation.unit+'. '+deviation.description};st.investigations.unshift(c);record('Investigation opened',c.title+' · owner '+c.owner+'.');st.view='investigations';
    } else if(form.dataset.form==='edit-case'){
      const c=st.investigations.find(x=>x.id===form.dataset.id);if(!c)throw new Error('Investigation not found.');if(d.note.trim().length<10)throw new Error('Record an action, finding or resolution evidence.');Object.assign(c,{owner:d.owner.trim(),status:d.status,note:d.note.trim(),updated:new Date().toISOString()});record('Investigation updated',c.title+' · '+c.status+'.',st.plants.find(x=>x.id===c.plant));
    } else if(form.dataset.form==='effort'){
      const hours=Number(d.hours);if(!Number.isFinite(hours)||hours<=0||hours>168)throw new Error('Record between 0.1 and 168 hours.');p().effort.push({id:C.uid('effort'),category:d.category,hours,person:d.person.trim(),note:d.note.trim(),at:new Date().toISOString()});record('Onboarding effort recorded',num(hours,1)+' active hours · '+d.category+'.');
    }
    close();save();render();toast('Saved to this browser workspace.');
  }catch(err){error(err.message);}});
  document.getElementById('dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
  save();render();
})();
